      ref={rootRef}
      role="listbox"
      tabIndex={0}
      aria-label="Option wheel"
      className={cn(
        "relative w-full h-full overflow-hidden select-none touch-none outline-none",
        isDragging ? "cursor-grabbing" : "cursor-grab",
        className
